WITH parsed AS (SELECT id, plan, effective_from, currency, discounts, SLICE(tier_limits, 1, 2) AS first_two_limits, AGGREGATE(tier_prices, 0.0D, (acc, p) -> acc + p, acc -> ROUND(acc / SIZE(tier_prices), 2)) AS avg_tier_price FROM price_tiers WHERE currency IN ('USD', 'EUR', 'THB')) SELECT CASE WHEN avg_tier_price >= 27 THEN 'HIGH' ELSE 'LOW' END AS avg_tier_price_tier, ROUND(AVG(avg_tier_price), 2) AS avg_avg_tier_price, SIZE(COLLECT_SET(plan)) AS num_plans, PERCENTILE_APPROX(avg_tier_price, 0.9) AS avg_tier_price_p90, COUNT(*) FILTER (WHERE plan = 'starter') AS starter_rows, COUNT(DISTINCT id) AS distinct_ids, SIZE(COLLECT_SET(currency)) AS num_currencies FROM parsed GROUP BY 1 ORDER BY avg_tier_price_p90 DESC;
